    ["orb.policy.choose_resolved_wishlist"] = "Choose a resolved Wishlist first.",
    ["orb.policy.name"] = "EchoWeaver Orb policy",
    ["orb.policy.no_safe_target"] = "No safe target or approved recyclable offer. Resolve the offer manually.",
    ["orb.policy.targets_exceed"] = "Targets exceed 79 rolled and 6 locked copies. Confirm the locked targets in the Wishlist editor.",
    ["orb.policy.targets_invalid"] = "The target list is invalid.",
    ["orb.recovery.attribution"] = "Your Echoes show the recorded gain, but an earlier unconfirmed attempt could have caused it. This action cannot be confirmed. Its record and exposure are kept. Stop, then open Orbs for the explicit checked Continue exit, or use that exit during passive recovery after reload. No spending restarts.",
    ["orb.recovery.board"] = "A choice for the earlier Orb action is recorded, but an Echo choice is open in the game. Nexus checks the result only while no Echo choice is open; Recheck cannot close it. Taking an Echo from that choice changes your Echoes, and Nexus then cannot confirm the earlier action.",
    ["orb.recovery.charges"] = "A choice for the earlier Orb action is recorded, but the Orb balance shown is {observed} and the record requires {expected} (one Orb less than before the action). Recheck asks the game for the current balance. While the balance differs, Nexus cannot confirm the action. The record and its spending exposure are kept.",
    ["orb.recovery.checking"] = "An earlier Orb action is unresolved. Another game action or an incomplete offer is visible. Nexus is waiting, read-only. Nothing will be sent.",
    ["orb.recovery.host"] = "A choice for the earlier Orb action is recorded. Another game action is still in flight. Nexus is waiting, read-only, until it ends. Nothing will be sent.",
    ["orb.recovery.loadout"] = "The original loadout of the earlier Orb action cannot be verified. Nexus cannot confirm that action.",
    ["orb.recovery.loadout_unknown"] = "An earlier Orb action is unresolved. The game has not yet sent this character's build-slot data since it loaded, so Nexus cannot check the original loadout yet. Nexus is waiting, read-only, and records nothing until then: if an Orb offer is open, a choice made in it now cannot be recorded for the earlier action. Nothing will be sent.",
    ["orb.recovery.offer"] = "A choice for the earlier Orb action is recorded: {echo}. The game still reports its Orb offer as open. If you have not chosen in the game's offer window since the reload, choose {echo_again} there; a different Echo cannot confirm this action. Nexus then waits, read-only, for the matching result. Nexus will not choose or spend.",
    ["orb.recovery.offer_open"] = "The earlier Orb offer is still open. Choose an Echo in the game's offer window. Nexus will record that choice and wait for the matching result. Nexus will not choose or spend.",
    ["orb.recovery.offer_open_blind"] = "The earlier Orb offer is still open, but this client cannot observe a manual choice. If you choose in the game, Nexus cannot confirm the earlier action afterwards.",
    ["orb.recovery.offer_open_proposed"] = "The earlier Orb offer is still open. Before the reload Nexus proposed {echo} for it, and that call was refused before it reached the game. Nexus can confirm this action only if you choose that same Echo in the game's offer window. If you choose a different Echo, Nexus cannot confirm the action. The record and its spending exposure are kept.",
    ["orb.recovery.offer_unmatched"] = "An Orb offer is open, but the Orb balance or rolled Echoes do not match the saved record of the earlier action. Nexus cannot confirm the earlier action from this offer. Resolve the offer in the game.",
    ["orb.recovery.ownership"] = "A choice for the earlier Orb action is recorded. Echo ownership does not show the chosen Echo yet. Nexus is waiting for an ownership response that shows it. Recheck requests one. Nothing will be sent.",
    ["orb.recovery.permanent_changed"] = "Locked Echoes changed since the earlier Orb action. Nexus cannot confirm that action.",
    ["orb.recovery.unobservable"] = "The earlier Orb action could not be linked to an observed result. The game gives no record of which choice belonged to it, so Nexus cannot confirm it, and Recheck cannot settle it. The record, its spending exposure, and the block on new Orb runs and ordinary rolling are kept. Nothing is retried, refunded or deleted.",
    ["orb.recovery.wait_fresh_asked"] = "A choice for the earlier Orb action is recorded, and Echo ownership already shows the chosen Echo. Nexus needs an ownership response newer than its first read after the reload, and asked the game once for one. Recheck requests one more. No Orb and no choice will be sent.",
    ["orb.recovery.wait_offer"] = "The earlier Orb action is unresolved and no Orb offer is open. If the game opens an offer that matches the saved record and you choose in the game's offer window, Nexus records that choice at the moment you make it, unless another game action is in flight at that moment. Nexus cannot tell whether the game refused the spend.",
    ["orb.recovery.wait_offer_blind"] = "The earlier Orb action is unresolved and no Orb offer is open. This client cannot observe a manual choice, so Nexus cannot confirm the earlier action if its offer opens later.",
    ["orb.recovery.wait_result"] = "A choice for the earlier Orb action is recorded. Nexus is waiting for a fresh ownership response that matches it exactly. Recheck requests one. Nothing will be sent.",
