    -- v33 B/C (hand-reviewed, not generated): Appearance background opacity
    -- (ui/Theme.lua) and the 8 accepted FAQ groups (FAQ_DRAFT r3, ui/Help.lua).
    ["theme.menu.opacity_choice"] = "Background opacity: {percent}%",
    ["theme.menu.opacity_default"] = "Background opacity: 100% (default)",
    ["theme.menu.unknown_opacity"] = "Saved background opacity \"{value}\" is not in this build; it stays saved.",
    ["theme.tooltip.opacity"] = "Changes only how see-through Nexus window backgrounds are; text, buttons and the difficulty card stay solid. 100% is the default look and clears the choice.",
    ["help.label.faq_echo_not_counted_question"] = "Why doesn't an Echo I can see count for my Wishlist?",
    ["help.body.faq_echo_not_counted_answer"] = "A target is one exact Echo at one exact quality. A lower-quality copy does not count for a higher-quality target; on the panel, an offer at another quality can show Wrong quality. An Echo your Wishlist does not ask for never counts. Only copies you have count, up to the copies the plan asks for; locked copies count only up to its locked targets. Copies above a target are extras. See the Wishlists tab above.",
    ["help.label.faq_orb_start_maximum_question"] = "Does Auto ON start an Orb run, and what is the maximum?",
    ["help.body.faq_orb_start_maximum_answer"] = "No. Auto never starts an Orb run. A run starts only when you open Orbs, check the maximum and click Start; starting it turns ordinary Automation off and does not turn it back on. The maximum is a limit, not a goal. Nexus uses one Orb per replacement and stops when your rolled targets are complete, so it can use fewer. Orbs used counts spent Orbs against the maximum, which does not change during a run. Until you type an amount, it follows your confirmed Orb balance, up to 1000.",
    ["help.label.faq_orb_blocked_question"] = "Why can't I start an Orb run, or why did it stop early?",
    ["help.body.faq_orb_blocked_answer"] = "Open the Orb window: it shows what is blocked, then what you can do now. An Orb action without a confirmed result blocks new runs until it settles, or until you use Continue... where it is offered. A run ends when your rolled targets are complete or no safe source is left. Changing the active loadout, assignment or targets pauses it. Orb mode never changes locked Echo slots. A reload does not settle an unknown result. Do not clear saved data. See the Orbs tab above.",
    ["help.label.faq_auto_replace_build_question"] = "Can Auto replace a Saved Build that has Echoes I value?",
    ["help.body.faq_auto_replace_build_answer"] = "Yes, while Auto is ON. After a finished run, Nexus may save it over your active Saved Build when overall Wishlist progress is higher, or equal with cleanup. It counts Wishlist progress, not Orbs spent, so an Echo you got with Orbs can be lost. At level 80 after a finished run, turning Auto ON or changing the assigned Wishlist can lead to a replacement without a new run. Saving edits to the assigned Wishlist can also lead to a replacement without a new run. Nexus cannot undo a save, and Unassign does not restore a Saved Build. There is no separate automatic-save switch: keep Auto OFF to leave it unchanged.",
    ["help.label.faq_hidden_panel_reload_question"] = "Does a hidden panel stay hidden after a reload?",
    ["help.body.faq_hidden_panel_reload_answer"] = "Yes. Hide Nexus Panel is saved as your choice, so the panel stays hidden after a reload or login. Type /nexus panel to show it again. If Nexus's saved data is read-only, the choice lasts this session only. Hiding changes no Auto setting.",
    ["help.label.faq_library_empty_question"] = "Why is the Build Library empty?",
    ["help.body.faq_library_empty_answer"] = "Check the scope: All Shared, or Mine (your Saved Builds and shared listings). The class button can limit the list to your current class; click it to switch between your class and all classes. Require both DPS records lists only builds with both a Training Dummy and a Lich King record this client holds; uncheck it to drop that requirement. Updating results... means a filter change is still applying, and a gray Explore control means shared views are loading or unavailable (/nexus loading). The list shows only what this client has stored. See the Sharing tab above.",
    ["help.label.faq_before_reload_question"] = "Something went wrong. What do I do before a reload?",
    ["help.body.faq_before_reload_answer"] = "Do not reload, relog or change builds first. Type /nexus report, click Copy summary and paste it into your report. Add your exact build (/nexus update shows it), what happened versus what you expected, and Auto ON or OFF. If reporting fails or says Not prepared, say so and send what you have. Never post the report file in public. See the Problems tab above.",
    ["help.label.faq_random_roll_leveling_question"] = "Can Nexus pick Echoes while I level without a Wishlist?",
    ["help.body.faq_random_roll_leveling_answer"] = "Yes, with Random Roll, an optional mode. Type /nexus leveling on or /nexus leveling off; /nexus leveling alone shows whether it is ON or OFF. It picks only when no Wishlist is assigned, at levels 2 to 79, with Auto ON and its Take permission allowed. Turning it on does not turn Auto ON. It takes the highest-rarity Echo offered (the first offer on a tie), not a random one. If an offer's rarity is unknown, it waits: pick by hand. It never rerolls, banishes, freezes, spends, saves or uses Orbs, and it makes no new pick at level 80. An assigned Wishlist always uses the normal rules instead.",
}
